/**
 * data/index.js — Barrel for the descriptor data.
 *
 * Every game object lives here as a descriptor, one file per object: descriptor
 * id `knot` → `data/knot.js` exporting `KNOT_DESCRIPTOR` (see
 * descriptorExportName in dev/tools/geometryEditor/emitDescriptor.js). Files are
 * generated by the geometry editor (dev/tools/geometryEditor.html → Save).
 *
 * Descriptors are raw JSON literals with only non-default fields;
 * gameBuilder.js / the editor normalize them on load (normalizeDescriptor).
 * The table-driven entity files keep their variant tables (BASE_VARIANTS /
 * MOB_VARIANTS — mobs compose the per-archetype variant files in `data/mobs/`
 * into the barrel) — their descriptors are derived from those tables and are
 * NOT edited through the editor yet.
 *
 * Not descriptor-driven (parity gaps, see dev/docs/futureWork.md): fruit trees keep
 * their hard-coded builder (worldObjects/fruitTree/).
 */
import { OPEN_TREASURE_CHEST_DESCRIPTOR } from './openTreasureChest.js';
import { BASE_DESCRIPTOR } from './base.js';
import { BEACH_DRIFTWOOD_DESCRIPTOR } from './beachDriftwood.js';
import { BUSH_DESCRIPTOR } from './bush.js';
import { CENSER_SAINT_DESCRIPTOR } from './censerSaint.js';
import { CHAMPION_DESCRIPTOR } from './champion.js';
import { TREASURE_CHEST_DESCRIPTOR } from './treasureChest.js';
import { CINDERBLOOM_DESCRIPTOR } from './cinderbloom.js';
import { DESERT_SCRUB_DESCRIPTOR } from './desertScrub.js';
import { DROWNED_COPYIST_DESCRIPTOR } from './drownedCopyist.js';
import { EDEN_MUSHROOM_DESCRIPTOR } from './edenMushroom.js';
import { EDEN_SHROOMLET_DESCRIPTOR } from './edenShroomlet.js';
import { ERRATA_SLIP_DESCRIPTOR } from './errataSlip.js';
import { FOOLS_FIRE_DESCRIPTOR } from './foolsFire.js';
import { GILDED_INITIAL_DESCRIPTOR } from './gildedInitial.js';
import { GROVE_DESCRIPTOR } from './grove.js';
import { HALF_DRAWN_OBELISK_DESCRIPTOR } from './halfDrawnObelisk.js';
import { HILL_DESCRIPTOR } from './hill.js';
import { KNOT_DESCRIPTOR } from './knot.js';
import { LISTENER_LICHEN_DESCRIPTOR } from './listenerLichen.js';
import { MARSH_REEDS_DESCRIPTOR } from './marshReeds.js';
import { MOB_DESCRIPTOR } from './mob.js';
import { MOUNTAIN_DESCRIPTOR } from './mountain.js';
import { NULL_LILY_DESCRIPTOR } from './nullLily.js';
import { OUROBOROS_LOOP_DESCRIPTOR } from './ouroborosLoop.js';
import { PALIMPSEST_SLAB_DESCRIPTOR } from './palimpsestSlab.js';
import { PERIDEXION_TREE_DESCRIPTOR } from './peridexionTree.js';
import { PLAINS_GRASS_DESCRIPTOR } from './plainsGrass.js';
import { PLATEAU_MOUND_DESCRIPTOR } from './plateauMound.js';
import { SAINTS_RIB_DESCRIPTOR } from './saintsRib.js';
import { SCORIA_ROSE_DESCRIPTOR } from './scoriaRose.js';
